import html


def customer_maintenance_html(api_version):
    page = r"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <meta name="color-scheme" content="dark">
  <title>VaultLink Security Maintenance</title>
  <style>
    :root{--bg:#0b1013;--band:#11181d;--surface:#182229;--surface2:#202c34;--field:#070a0c;--line:#354650;--text:#f4f7f8;--muted:#a8b7bf;--green:#58e28a;--blue:#5fc4e8;--yellow:#ffd166;--red:#ff7e78}*{box-sizing:border-box}html{background:var(--bg);color:var(--text);font-family:Segoe UI,Arial,sans-serif;letter-spacing:0}body{margin:0;min-width:0;background:var(--bg)}button,select{font:inherit;letter-spacing:0}header{border-bottom:1px solid var(--line);background:var(--band)}header>div,main,footer>div{width:min(1240px,calc(100% - 32px));margin:auto}header>div{display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:64px}.brand{font-size:1rem;font-weight:800}nav{display:flex;flex-wrap:wrap;gap:8px}nav a{padding:8px 9px;border:1px solid var(--line);border-radius:5px;color:var(--text);font-size:.72rem;font-weight:800;text-decoration:none}main{padding:32px 0 48px}h1{margin:0;font-size:2rem;line-height:1.1}h2{margin:0;font-size:1.25rem}h3{margin:0;font-size:1rem}p{color:var(--muted);line-height:1.5}.lead{max-width:900px;margin:9px 0 0}.privacy{margin:18px 0;padding:14px 16px;border-left:4px solid var(--green);background:var(--band);color:var(--muted);line-height:1.5}.controls{display:grid;grid-template-columns:minmax(190px,1fr) minmax(190px,1fr) repeat(8,auto);gap:8px;align-items:end;padding:14px;border:1px solid var(--line);background:var(--band)}label,.eyebrow{display:block;margin-bottom:6px;color:var(--yellow);font-size:.68rem;font-weight:800;text-transform:uppercase}select,button{min-height:40px;border:1px solid var(--line);border-radius:5px}select{width:100%;padding:0 10px;background:var(--field);color:var(--text)}button{padding:0 11px;background:#273640;color:var(--text);font-size:.72rem;font-weight:800;cursor:pointer}button.primary{background:var(--green);color:#031009;border-color:var(--green)}button.blue{background:var(--blue);color:#031014;border-color:var(--blue)}button.export{background:var(--yellow);color:#171100;border-color:var(--yellow)}button:disabled,select:disabled{cursor:not-allowed;opacity:.45}.status{min-height:34px;padding:10px 0;color:var(--muted)}.status.good{color:var(--green)}.status.bad{color:var(--red)}.metrics{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));margin:3px 0 22px;border:1px solid var(--line)}.metric{min-width:0;padding:13px;border-right:1px solid var(--line)}.metric:last-child{border-right:0}.metric span{display:block;color:var(--muted);font-size:.65rem;font-weight:700;text-transform:uppercase}.metric strong{display:block;margin-top:6px;overflow-wrap:anywhere;font-size:.95rem}.layout{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:18px}.section{padding-top:20px;border-top:1px solid var(--line)}.section-head{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:12px}.section-head p{max-width:620px;margin:0;text-align:right}.tasks{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.task{display:grid;grid-template-columns:auto minmax(0,1fr);gap:12px;min-width:0;padding:15px;border:1px solid var(--line);border-radius:7px;background:var(--surface)}.task.reviewed{border-color:var(--green);background:#14231c}.task input{width:19px;height:19px;margin:2px 0 0;accent-color:var(--green)}.task p{margin:7px 0 0;font-size:.86rem}.task-meta{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:5px}.tag{padding:3px 6px;border:1px solid var(--line);border-radius:4px;color:var(--blue);font-size:.64rem;font-weight:800;text-transform:uppercase}.due{color:var(--yellow)}.expected{margin-top:10px;padding-top:9px;border-top:1px solid var(--line);color:var(--muted);font-size:.8rem;line-height:1.4}.expected strong{color:var(--yellow)}.sidebar{display:flex;flex-direction:column;gap:10px}.routine,.boundary{padding:14px;border:1px solid var(--line);border-radius:7px;background:var(--surface)}.routine.active{border-color:var(--blue)}.routine button{width:100%;margin-top:9px}.routine p,.boundary p{margin:7px 0 0;font-size:.84rem}.boundary{border-top:3px solid var(--yellow)}.stack{display:grid;gap:9px}.empty{padding:24px;border:1px dashed var(--line);color:var(--muted);text-align:center}footer{border-top:1px solid var(--line);background:var(--band)}footer>div{padding:20px 0;color:var(--muted);font-size:.82rem;line-height:1.45}@media(max-width:1120px){.controls{grid-template-columns:repeat(4,minmax(0,1fr))}.controls>div{grid-column:span 2}.layout{grid-template-columns:1fr}.sidebar{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.metrics{grid-template-columns:repeat(4,minmax(0,1fr))}.metric:nth-child(4){border-right:0}}@media(max-width:700px){header>div{align-items:flex-start;flex-direction:column;padding:14px 0}main{padding-top:24px}h1{font-size:1.65rem}.controls{grid-template-columns:1fr}.controls>div{grid-column:auto}.controls button{width:100%}.metrics,.tasks,.sidebar{grid-template-columns:1fr}.metric{border-right:0;border-bottom:1px solid var(--line)}.metric:last-child{border-bottom:0}.section-head{align-items:flex-start;flex-direction:column}.section-head p{text-align:left}}
  </style>
</head>
<body>
  <header><div><div class="brand">VaultLink Security Maintenance</div><nav><a href="/workspace">WORKSPACE</a><a href="/retention">RETENTION</a><a href="/data-control">DATA</a><a href="/recovery-kit">KIT</a><a href="/backup-verification">BACKUPS</a><a href="/diagnostics">DIAGNOSTICS</a><a href="/trust">TRUST</a><a href="/status">STATUS</a></nav></div></header>
  <main>
    <h1>Keep recovery controls practiced</h1>
    <p class="lead">Use thirty-two fixed maintenance tasks and six routines without entering a name, note, path, file, key, PIN, result, or customer record.</p>
    <div class="privacy">Review progress exists only in the current tab and disappears on reload. This page cannot inspect a PC, run a scan, change Windows, complete a task remotely, or receive desktop maintenance history.</div>
    <div class="controls">
      <div><label for="category">Category</label><select id="category" disabled></select></div>
      <div><label for="routine">Routine</label><select id="routine" disabled></select></div>
      <button id="reset" type="button" disabled>RESET</button><button id="next" class="primary" type="button" disabled>REVIEW NEXT</button><button id="routineAll" class="blue" type="button" disabled>REVIEW ROUTINE</button><button id="all" type="button" disabled>REVIEW ALL</button><button id="copy" type="button" disabled>COPY</button><button id="calendar" type="button" disabled>CALENDAR</button><button id="print" type="button" disabled>PRINT</button><button id="export" class="export" type="button" disabled>EXPORT JSON</button>
    </div>
    <div id="status" class="status" role="status" aria-live="polite">Loading the fixed maintenance guide...</div>
    <div id="workspace" hidden>
      <div id="metrics" class="metrics"></div>
      <div class="layout">
        <section class="section"><div class="section-head"><div><div class="eyebrow">CURRENT-TAB REVIEW</div><h2>Maintenance tasks</h2></div><p>Checking a task is a browser review marker only. Desktop completion dates remain local.</p></div><div id="tasks" class="tasks"></div></section>
        <aside class="sidebar">
          <section class="section"><div class="eyebrow">FIXED ROUTINES</div><h2>Routine map</h2><div id="routines" class="stack"></div></section>
          <section class="section"><div class="eyebrow">PRIVACY BOUNDARIES</div><div id="boundaries" class="stack"></div></section>
          <section class="section"><div class="eyebrow">LIMITATIONS</div><div id="limitations" class="stack"></div></section>
        </aside>
      </div>
    </div>
  </main>
  <footer><div>API __API_VERSION__. No browser storage, progress submission, account, license proof, path, file, local result, maintenance command, or free-form note API is used.</div></footer>
  <script>
    const $=id=>document.getElementById(id);const state={payload:null,category:"all",routine:"all",reviewed:new Set()};const value=input=>String(input??"");
    function add(parent,tag,text,className=""){const node=document.createElement(tag);node.textContent=value(text);if(className)node.className=className;parent.append(node);return node;}function setStatus(text,tone=""){$("status").textContent=text;$("status").className=`status ${tone}`;}function metric(label,text){const node=document.createElement("div");node.className="metric";add(node,"span",label);add(node,"strong",text);return node;}function knownIds(){return new Set((state.payload?.tasks||[]).map(item=>item.id));}function selectedRoutine(){return(state.payload?.routines||[]).find(item=>item.id===state.routine)||null;}function routineIds(){const item=selectedRoutine();return item?new Set(item.task_ids):knownIds();}
    function visibleTasks(){let items=state.payload?.tasks||[];if(state.category!=="all")items=items.filter(item=>item.category_id===state.category);if(state.routine!=="all"){const allowed=routineIds();items=items.filter(item=>allowed.has(item.id));}return items;}
    function safeReceipt(){const known=knownIds();const reviewed=[...state.reviewed].filter(id=>known.has(id)).sort();return{schema_version:1,report_type:"VaultLink Privacy-Safe Browser Maintenance Review",generated_at_utc:new Date().toISOString(),api_version:state.payload.api_version,service_mode:state.payload.service_status.mode,signed_desktop_version:state.payload.signed_release.version||"",selected_category_id:state.category,selected_routine_id:state.routine,reviewed_task_ids:reviewed,reviewed_count:reviewed.length,task_count:known.size,privacy_notice:"No name, contact, license proof, receipt, key, PIN, USB secret, path, filename, file content, local result, completion time, customer record, screenshot, process list, or free-form note is included."};}
    function renderMetrics(){const root=$("metrics");root.replaceChildren();const visible=visibleTasks();const reviewed=[...state.reviewed].filter(id=>knownIds().has(id)).length;[["API",state.payload.api_version],["Service",state.payload.service_status.mode],["Signed desktop",state.payload.signed_release.version||"Not published"],["Categories",state.payload.category_count],["Tasks",state.payload.task_count],["Routines",state.payload.routine_count],["Reviewed",`${reviewed} / ${state.payload.task_count}`]].forEach(row=>root.append(metric(...row)));setStatus(`${visible.length} fixed task(s) visible. Browser review is not a desktop completion record.`,"good");}
    function categoryTitle(id){return(state.payload.categories.find(item=>item.id===id)||{}).title||id;}function renderTasks(){const root=$("tasks");root.replaceChildren();const items=visibleTasks();if(!items.length){add(root,"div","No fixed tasks match this filter.","empty");}items.forEach(item=>{const card=document.createElement("article");card.className=`task ${state.reviewed.has(item.id)?"reviewed":""}`;const box=document.createElement("input");box.type="checkbox";box.checked=state.reviewed.has(item.id);box.setAttribute("aria-label",`Review ${item.title}`);box.addEventListener("change",()=>{box.checked?state.reviewed.add(item.id):state.reviewed.delete(item.id);renderTasks();});const body=document.createElement("div");const meta=document.createElement("div");meta.className="task-meta";add(meta,"span",categoryTitle(item.category_id),"tag");add(meta,"span",`${item.cadence_days} DAYS`,"tag due");body.append(meta);add(body,"h3",item.title);add(body,"p",item.action);const expected=document.createElement("div");expected.className="expected";add(expected,"strong","Expected: ");expected.append(document.createTextNode(item.expected));body.append(expected);card.append(box,body);root.append(card);});renderMetrics();}
    function renderRoutines(){const root=$("routines");root.replaceChildren();state.payload.routines.forEach(item=>{const card=document.createElement("article");card.className=`routine ${state.routine===item.id?"active":""}`;add(card,"h3",item.label);add(card,"p",item.summary);add(card,"div",`${item.task_ids.length} fixed tasks`,"expected");const button=add(card,"button","USE ROUTINE");button.type="button";button.addEventListener("click",()=>{state.routine=item.id;$("routine").value=item.id;renderTasks();renderRoutines();});root.append(card);});}
    function render(data){state.payload=data;const category=$("category");category.replaceChildren();[["all","All categories"],...data.categories.map(item=>[item.id,item.title])].forEach(([id,label])=>{const option=document.createElement("option");option.value=id;option.textContent=label;category.append(option);});const routine=$("routine");routine.replaceChildren();[["all","All tasks"],...data.routines.map(item=>[item.id,item.label])].forEach(([id,label])=>{const option=document.createElement("option");option.value=id;option.textContent=label;routine.append(option);});category.disabled=false;routine.disabled=false;["reset","next","routineAll","all","copy","calendar","print","export"].forEach(id=>$(id).disabled=false);[["boundaries",data.privacy_boundaries],["limitations",data.limitations]].forEach(([id,items])=>{const root=$(id);items.forEach(text=>{const card=document.createElement("article");card.className="boundary";add(card,"p",text);root.append(card);});});$("workspace").hidden=false;renderTasks();renderRoutines();}
    async function load(){try{const response=await fetch("/api/v1/maintenance-guide",{headers:{Accept:"application/json"},cache:"no-store",redirect:"error"});const data=await response.json();if(!response.ok)throw new Error(data.message||"Maintenance guide could not be loaded.");render(data);}catch(error){setStatus(error.message||"Maintenance guide could not be loaded.","bad");}}
    function reset(){state.reviewed.clear();renderTasks();}function reviewNext(){const item=visibleTasks().find(entry=>!state.reviewed.has(entry.id));if(item)state.reviewed.add(item.id);renderTasks();}function reviewRoutine(){const ids=routineIds();state.payload.tasks.forEach(item=>{if(ids.has(item.id))state.reviewed.add(item.id);});renderTasks();}function reviewAll(){state.payload.tasks.forEach(item=>state.reviewed.add(item.id));renderTasks();}
    async function copySummary(){const report=safeReceipt();const lines=["VaultLink security maintenance review",`Reviewed fixed tasks: ${report.reviewed_count}/${report.task_count}`,`Category: ${report.selected_category_id} | Routine: ${report.selected_routine_id}`,`API: ${report.api_version} | Service: ${report.service_mode} | Signed desktop: ${report.signed_desktop_version||"not published"}`,report.privacy_notice];try{await navigator.clipboard.writeText(lines.join("\n"));setStatus("Privacy-safe maintenance summary copied.","good");}catch(_error){setStatus("Clipboard access was blocked by the browser.","bad");}}
    function download(name,type,text){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}function exportJson(){download("vaultlink-browser-maintenance-review.json","application/json",JSON.stringify(safeReceipt(),null,2));setStatus("Privacy-safe browser maintenance review exported.","good");}
    function escapeIcs(text){return value(text).replace(/\\/g,"\\\\").replace(/\r?\n/g,"\\n").replace(/,/g,"\\,").replace(/;/g,"\\;");}function ymd(date){return date.toISOString().slice(0,10).replaceAll("-","");}function exportCalendar(){const visible=visibleTasks();const base=new Date();const lines=["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//VaultLink//Security Maintenance//EN","CALSCALE:GREGORIAN","METHOD:PUBLISH"];visible.forEach(item=>{const due=new Date(base.getTime()+item.cadence_days*86400000);lines.push("BEGIN:VEVENT",`UID:vaultlink-maintenance-${escapeIcs(item.id)}-${ymd(due)}@local`,`DTSTAMP:${base.toISOString().replace(/[-:]/g,"").replace(/\.\d{3}Z$/,"Z")}`,`DTSTART;VALUE=DATE:${ymd(due)}`,`SUMMARY:${escapeIcs(`VaultLink: ${item.title}`)}`,`DESCRIPTION:${escapeIcs("Review this fixed maintenance task in the local VaultLink Security Maintenance Center. Do not place secrets or customer data in calendar notes.")}`,"END:VEVENT");});lines.push("END:VCALENDAR");download("vaultlink-maintenance-plan.ics","text/calendar",lines.join("\r\n")+"\r\n");setStatus(`Exported ${visible.length} fixed calendar reminder(s).`,"good");}
    $("category").addEventListener("change",event=>{state.category=event.target.value;renderTasks();});$("routine").addEventListener("change",event=>{state.routine=event.target.value;renderTasks();renderRoutines();});$("reset").addEventListener("click",reset);$("next").addEventListener("click",reviewNext);$("routineAll").addEventListener("click",reviewRoutine);$("all").addEventListener("click",reviewAll);$("copy").addEventListener("click",copySummary);$("calendar").addEventListener("click",exportCalendar);$("print").addEventListener("click",()=>window.print());$("export").addEventListener("click",exportJson);load();
  </script>
</body>
</html>"""
    return page.replace("__API_VERSION__", html.escape(str(api_version), quote=True))
